import {createHash} from 'node:crypto';
import {mockAtlas,atlasBeaches,atlasCatalog} from './nextjs-atlas.mjs';
import {directoryResponse} from './nextjs-directory.mjs';
import {event} from './nextjs-administration.mjs';
export const discoveryDirectory={...structuredClone(atlasBeaches),revision:'10',states:[{id:'NSW',name:'New South Wales'},{id:'VIC',name:'Victoria'}],areas:[{id:'nsw-coast',name:'Sydney Coast',state_id:'NSW',center:[151.2,-33.9],map_region:'example-bay',depth_count:6},{id:'example-area',name:'Example Area',state_id:'VIC',center:[145,-38],map_region:'example-bay',depth_count:9}],beaches:Array.from({length:15},(_,i)=>({id:i===0?'bondi':i===1?'portsea':'reef-'+String(i+1).padStart(2,'0'),name:i===0?'Bondi Beach':i===1?'Portsea Beach':'Reef Site '+String(i+1).padStart(2,'0'),state_id:i%2?'VIC':'NSW',state:i%2?'Victoria':'New South Wales',area_id:i%2?'example-area':'nsw-coast',area_name:i%2?'Example Area':'Sydney Coast',point:i%2?[145+i/1000,-38]:[151.2+i/1000,-33.9],region:'example-bay',waterbody:i===14?'quarry':'ocean',access_mode:i===13?'boat_only':'shore',activities:['freediving','ocean-swimming','spearfishing'],activity_status:'documented',entry_documented:i!==13,source_url:'https://example.invalid/site-'+i,facts:[{label:'Access',text:'Sourced access reference.',source_url:'https://example.invalid/access',reviewed_at:'2026-11-03'}],nearby_checked_stays:i%3===0?2:0,depth_evidence:i===14?[{depth_m:15,kind:'reported',reference:'Example source',source_url:'https://example.invalid/depth'}]:[],aliases:i===2?['Rock shelf']:[]}))};
export const discoverySummaries={beaches:discoveryDirectory.beaches.map((b,i)=>({id:b.id,start_label:'Mapped 0 m reference',datum:'AHD',survey_date:'2020',depths:Object.fromEntries([5,10,15,20].map(d=>[d,{distance_m:100+i*60+d}]))}))};
export async function mockDiscovery(page,base,{directory=()=>discoveryDirectory,location={country:null,state:null}}={}){await mockAtlas(page,base);await page.route('**/neon-config.json*',r=>r.fulfill({json:{enabled:true,backbone:true,apiUrl:base+'/',authUrl:'https://auth.invalid'}}));const files=Object.fromEntries([['beaches.json',discoveryDirectory],['data/catalog.json',atlasCatalog]].map(([path,data])=>{const body=JSON.stringify(data);return [path,{hash:createHash('sha256').update(body).digest('hex'),bytes:Buffer.byteLength(body),label:path}];}));await page.route('**/data/downloads.json*',r=>r.fulfill({json:{version:1,revision:'discovery-fixture',files,regions:{}}}));await page.route('**/v1/sites/catalog*',async r=>{const value=structuredClone(directory());await r.fulfill({json:value});});await page.route('**/beaches.json*',r=>r.fulfill({json:discoveryDirectory}));await page.route('**/sites-snapshot.json*',r=>r.fulfill({json:discoveryDirectory}));await page.route('**/data/beach-summaries.json*',r=>r.fulfill({json:discoverySummaries}));await page.route('**/api/location',r=>r.fulfill({json:location}));await page.route('**/v1/discover/popular*',r=>r.fulfill({json:{places:['reef-04','reef-03']}}));await page.route(/\/v1\/directory(?:\?|$)/,r=>r.fulfill({json:directoryResponse(new URL(r.request().url()).searchParams)}));await page.route(/\/v1\/events(?:\?|$)/,r=>r.fulfill({json:{events:[event]}}));}
